SELECT m.first_name, m.last_name, ma.major_name, COUNT(CASE WHEN CAST(e.approved AS boolean) = true THEN 1 END) as approved_count, COUNT(CASE WHEN CAST(e.approved AS boolean) = false THEN 1 END) as rejected_count, ROUND(COUNT(CASE WHEN CAST(e.approved AS boolean) = true THEN 1 END)::numeric / COUNT(*), 2) as approval_rate FROM expense e JOIN member m ON e.link_to_member = m.member_id JOIN major ma ON m.link_to_major = ma.major_id GROUP BY m.member_id, m.first_name, m.last_name, ma.major_name ORDER BY approved_count DESC LIMIT 10;
